Dataspatium.assets.register("presets/api/dataportal.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"dataportal\",\n  \"name\": \"Sveriges dataportal (sök datamängder)\",\n  \"publisher\": \"Digg, Myndigheten för digital förvaltning\",\n  \"description\": \"Sök bland alla myndigheters, regioners och kommuners publicerade datamängder. Resultatet är en tabell med titel, utgivare, format och nedladdningslänk; filer importeras sedan via Filer.\",\n  \"docs\": \"https://www.dataportal.se/\",\n  \"license\": { \"name\": \"Metadata: CC0 1.0\", \"url\": \"https://creativecommons.org/publicdomain/zero/1.0/\" },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://admin.dataportal.se/store\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 5, \"perSeconds\": 2 },\n  \"endpoints\": [\n    {\n      \"id\": \"search\",\n      \"name\": \"Sök datamängder\",\n      \"method\": \"GET\",\n      \"path\": \"/search\",\n      \"params\": [\n        { \"name\": \"q\", \"in\": \"template\", \"label\": \"Sökord\", \"type\": \"string\", \"required\": true, \"example\": \"befolkning\" },\n        { \"name\": \"type\", \"in\": \"query\", \"type\": \"string\", \"default\": \"solr\", \"hidden\": true },\n        { \"name\": \"query\", \"in\": \"query\", \"type\": \"string\", \"hidden\": true, \"template\": \"(title:\\\"{q}\\\" OR description:\\\"{q}\\\") AND rdfType:http\\\\://www.w3.org/ns/dcat#Dataset\" },\n        { \"name\": \"limit\", \"in\": \"query\", \"type\": \"number\", \"default\": 50, \"hidden\": true }\n      ],\n      \"pagination\": { \"type\": \"offset\", \"param\": \"offset\", \"sizeParam\": \"limit\", \"size\": 50, \"start\": 0, \"totalPath\": \"results\", \"maxPages\": 4 },\n      \"response\": { \"format\": \"entryscape\" },\n      \"dataset\": { \"name\": \"Dataportalen: {q}\" }\n    }\n  ],\n  \"i18n\": {\n    \"en\": {\"name\": \"Sweden's data portal (search datasets)\", \"publisher\": \"Digg, Swedish Agency for Digital Government\", \"description\": \"Search the published datasets of all Swedish agencies, regions and municipalities. The result is a table with title, publisher, format and download link; files are then imported through Files.\", \"endpoints\": {\"search\": {\"name\": \"Search datasets\", \"params\": {\"q\": {\"label\": \"Search words\"}}}}, \"dataset\": {\"search\": \"Data portal: {q}\"}},\n    \"da\": {\"name\": \"Sveriges dataportal (søg datasæt)\", \"publisher\": \"Digg, den svenske myndighed for digital forvaltning\", \"description\": \"Søg blandt alle svenske myndigheders, regioners og kommuners offentliggjorte datasæt. Resultatet er en tabel med titel, udgiver, format og downloadlink; filer importeres derefter via Filer.\", \"endpoints\": {\"search\": {\"name\": \"Søg datasæt\", \"params\": {\"q\": {\"label\": \"Søgeord\"}}}}},\n    \"nb\": {\"name\": \"Sveriges dataportal (søk datasett)\", \"publisher\": \"Digg, den svenske etaten for digital forvaltning\", \"description\": \"Søk blant alle svenske etaters, regioners og kommuners publiserte datasett. Resultatet er en tabell med tittel, utgiver, format og nedlastingslenke; filer importeres deretter via Filer.\", \"endpoints\": {\"search\": {\"name\": \"Søk datasett\", \"params\": {\"q\": {\"label\": \"Søkeord\"}}}}},\n    \"fi\": {\"name\": \"Ruotsin dataportaali (hae aineistoja)\", \"publisher\": \"Digg, Ruotsin digitaalisen hallinnon virasto\", \"description\": \"Hae kaikkien Ruotsin viranomaisten, alueiden ja kuntien julkaisemia aineistoja. Tulos on taulukko, jossa on nimi, julkaisija, muoto ja latauslinkki; tiedostot tuodaan sen jälkeen kohdasta Tiedostot.\", \"endpoints\": {\"search\": {\"name\": \"Hae aineistoja\", \"params\": {\"q\": {\"label\": \"Hakusanat\"}}}}, \"dataset\": {\"search\": \"Dataportaali: {q}\"}},\n    \"is\": {\"name\": \"Gagnagátt Svíþjóðar (leita að gagnasöfnum)\", \"publisher\": \"Digg, stofnun Svíþjóðar um stafræna stjórnsýslu\", \"description\": \"Leitaðu meðal birtra gagnasafna allra sænskra stofnana, landshluta og sveitarfélaga. Niðurstaðan er tafla með heiti, útgefanda, sniði og niðurhalstengli; skrár eru síðan fluttar inn gegnum Skrár.\", \"endpoints\": {\"search\": {\"name\": \"Leita að gagnasöfnum\", \"params\": {\"q\": {\"label\": \"Leitarorð\"}}}}, \"dataset\": {\"search\": \"Gagnagáttin: {q}\"}}\n  }\n}\n");
